a = asanyarray(a)
if axis is None:
    # roll the flattened array
    n = a.size
    if n == 0:
        return a
    shift %= n
    indexes = concatenate((arange(n - shift, n), arange(n - shift)))
    res = a.take(indexes)
    return res.reshape(a.shape)

if isinstance(axis, tuple):
    # roll along each of the given axes, broadcasting `shift` so that
    # each axis may be shifted by a different amount
    for sh, ax in broadcast(shift, axis):
        ax = operator.index(ax)
        try:
            n = a.shape[ax]
        except IndexError:
            raise ValueError('axis must be >= %d and < %d'
                             % (-a.ndim, a.ndim))
        if n == 0:
            continue
        sh %= n
        indexes = concatenate((arange(n - sh, n), arange(n - sh)))
        a = a.take(indexes, ax)
    return a

try:
